using Kaff.Domain.Common;

namespace Kaff.Api.Features.DailyLogs.DraftExpense;

/// <summary>An engineer's expense. Stored as a draft; no posting.</summary>
/// <param name="EntryId">Generated by the device, so a retried sync is recognised and not counted twice.</param>
/// <param name="OccurredAt">When it happened on site, with the device's offset. Decides which day the entry belongs to.</param>
public sealed record Request(Guid? EntryId, DateTimeOffset? OccurredAt, string? Description, Money Amount);
